+std::vector<std::string> subwordStrings(const std::string& token, int minn,
+                                        int maxn) {
+  std::vector<std::string> result;
+  if (minn <= 0 || maxn <= 0) {
+    return result;
+  }
+  const std::string bounded = "<" + token + ">";
+  for (std::size_t start = 0; start < bounded.size(); ++start) {
+    for (int len = minn; len <= maxn; ++len) {
+      if (start + static_cast<std::size_t>(len) <= bounded.size()) {
+        result.push_back(bounded.substr(start, len));
+      }
+    }
+  }
+  return result;
+}
+
+std::vector<int> subwordIds(const std::string& token, int minn, int maxn,
+                            int bucket) {
+  std::vector<int> ids;
+  if (bucket <= 0 || minn <= 0 || maxn <= 0) {
+    return ids;
+  }
+  for (const std::string& ngram : subwordStrings(token, minn, maxn)) {
+    ids.push_back(static_cast<int>(fnv1a(ngram) % static_cast<std::uint32_t>(bucket)));
+  }
+  return ids;
+}
+
+std::vector<int> wordNgramIds(const std::vector<std::string>& tokens,
+                              int wordNgrams, int bucket) {
+  std::vector<int> ids;
+  if (bucket <= 0 || wordNgrams <= 1) {
+    return ids;
+  }
+  for (std::size_t i = 0; i < tokens.size(); ++i) {
+    std::string current = tokens[i];
+    for (int n = 2; n <= wordNgrams && i + static_cast<std::size_t>(n) <= tokens.size();
+         ++n) {
+      if (n > 2) {
+        current.push_back('\x1f');
+        current.append(tokens[i + n - 1]);
+      } else {
+        current = tokens[i] + '\x1f' + tokens[i + 1];
+      }
+      ids.push_back(static_cast<int>(fnv1a(current) %
+                                     static_cast<std::uint32_t>(bucket)));
+    }
+  }
+  return ids;
+}
