+double dot(const std::vector<float>& lhs, const std::vector<float>& rhs) {
+  double value = 0.0;
+  for (std::size_t i = 0; i < lhs.size(); ++i) {
+    value += static_cast<double>(lhs[i]) * static_cast<double>(rhs[i]);
+  }
+  return value;
+}
