+Components supervisedLineComponents(const Model& model,
+                                    const std::vector<std::string>& tokens) {
+  Components components;
+  for (const std::string& token : tokens) {
+    Components tokenParts = tokenComponents(model, token);
+    components.wordRows.insert(components.wordRows.end(), tokenParts.wordRows.begin(),
+                               tokenParts.wordRows.end());
+    components.bucketRows.insert(components.bucketRows.end(), tokenParts.bucketRows.begin(),
+                                 tokenParts.bucketRows.end());
+  }
+  for (int bucketId :
+       wordNgramIds(tokens, model.args.wordNgrams, model.args.bucket)) {
+    components.bucketRows.push_back(bucketId);
+  }
+  return components;
+}
