+std::vector<float> averageInput(const Model& model, const Components& components) {
+  std::vector<float> hidden(model.args.dim, 0.0f);
+  const double count = static_cast<double>(components.size());
+  if (count == 0.0) {
+    return hidden;
+  }
+  for (int index : components.wordRows) {
+    const std::vector<float>& values = model.inputWords[index];
+    for (int d = 0; d < model.args.dim; ++d) {
+      hidden[d] += values[d];
+    }
+  }
+  for (int index : components.bucketRows) {
+    const std::vector<float>* values = findBucketVector(model, index);
+    if (values == nullptr) {
+      continue;
+    }
+    for (int d = 0; d < model.args.dim; ++d) {
+      hidden[d] += (*values)[d];
+    }
+  }
+  for (float& value : hidden) {
+    value = static_cast<float>(value / count);
+  }
+  return hidden;
+}
+
+void applyInputGradient(Model& model, const Components& components,
+                        const std::vector<float>& grad) {
+  const double count = static_cast<double>(components.size());
+  if (count == 0.0) {
+    return;
+  }
+  const float scale = static_cast<float>(1.0 / count);
+  for (int index : components.wordRows) {
+    std::vector<float>& values = model.inputWords[index];
+    for (int d = 0; d < model.args.dim; ++d) {
+      values[d] += grad[d] * scale;
+    }
+  }
+  for (int index : components.bucketRows) {
+    std::vector<float>& values = ensureBucketVector(model, index);
+    for (int d = 0; d < model.args.dim; ++d) {
+      values[d] += grad[d] * scale;
+    }
+  }
+}
