+int runTrainingCommand(ModelKind kind, const std::vector<std::string>& argv) {
+  Args args = defaultArgsFor(kind);
+  if (argv.empty()) {
+    if (kind == ModelKind::kSupervised || kind == ModelKind::kSkipgram ||
+        kind == ModelKind::kCbow) {
+      std::cerr << "Empty input or output path.\n\n";
+      printTrainingHelp(args, std::cerr);
+      return 1;
+    }
+  }
+  std::optional<ParseError> error = parseTrainingArgs(argv, args);
+  if (error.has_value()) {
+    std::cerr << error->message << "\n\n";
+    printTrainingHelp(args, std::cerr);
+    return 1;
+  }
+  if (args.input.empty() || args.output.empty()) {
+    std::cerr << "Empty input or output path.\n\n";
+    printTrainingHelp(args, std::cerr);
+    return 1;
+  }
+
+  const bool supervised = kind == ModelKind::kSupervised;
+  const auto start = std::chrono::steady_clock::now();
+  Corpus corpus = readCorpus(args.input, supervised, args.label);
+  Dictionary dict = buildDictionary(corpus, args, supervised);
+  const std::int64_t totalWords = [&]() {
+    std::int64_t words = 0;
+    for (const Example& example : corpus.examples) {
+      words += static_cast<std::int64_t>(example.wordIds.size());
+    }
+    return words;
+  }();
+
+  Model model;
+  model.args = args;
+  model.dict = std::move(dict);
+  initializeModel(model);
+  if (model.dict.numWords == 0) {
+    const auto end = std::chrono::steady_clock::now();
+    const double seconds =
+        std::chrono::duration<double>(end - start).count();
+    printTrainingProgress(args, model.dict, -std::numeric_limits<double>::quiet_NaN(),
+                          totalWords, seconds);
+    throw std::invalid_argument("Empty vocabulary. Try a smaller -minCount value.");
+  }
+
+  double loss = -std::numeric_limits<double>::quiet_NaN();
+  if (kind == ModelKind::kSupervised) {
+    loss = trainSupervised(model, corpus);
+  } else if (kind == ModelKind::kSkipgram) {
+    trainSkipgram(model, corpus);
+  } else {
+    trainCbow(model, corpus);
+  }
+
+  saveModel(model, modelPathForOutput(args.output));
+  saveVec(model, vecPathForOutput(args.output));
+
+  const auto end = std::chrono::steady_clock::now();
+  const double seconds = std::chrono::duration<double>(end - start).count();
+  printTrainingProgress(args, model.dict, loss, totalWords, seconds);
+  return 0;
+}
