  int autotunePredictions = 1;
  int autotuneDuration = 300;
  std::string autotuneModelSize;
  int cutoff = 0;
  bool retrain = false;
  bool qnorm = false;
  bool qout = false;
  int dsub = 2;
  ModelKind model = ModelKind::kSkipgram;
};

struct ParseError {
  std::string message;
};

struct Entry {
  std::string token;
  std::int64_t count = 0;
  bool isLabel = false;
};

struct Example {
  std::vector<std::string> wordTokens;
  std::vector<std::string> labelTokens;
  std::vector<int> wordIds;
  std::vector<int> labelIds;
};

struct Corpus {
  std::vector<Example> examples;
  std::int64_t totalLines = 0;
};

struct Dictionary {
  std::vector<Entry> entries;
  std::unordered_map<std::string, int> wordIndex;
  std::unordered_map<std::string, int> labelIndex;
  int numWords = 0;
  int numLabels = 0;
};

struct Components {
  std::vector<int> wordRows;
  std::vector<int> bucketRows;

  std::size_t size() const {
    return wordRows.size() + bucketRows.size();
  }
};

struct Model {
  Args args;
  Dictionary dict;
  bool quantized = false;
  std::vector<std::vector<float>> inputWords;
  std::unordered_map<int, std::vector<float>> inputBuckets;
  std::vector<std::vector<float>> outputRows;
};

struct Prediction {
  int labelIndex = -1;
  double score = 0.0;
};

constexpr const char* kMagic = "FTCLONE1";

std::string lossToString(LossKind loss) {
  switch (loss) {
    case LossKind::kNs:
      return "ns";
    case LossKind::kHs:
      return "hs";
    case LossKind::kSoftmax:
      return "softmax";
    case LossKind::kOneVsAll:
      return "one-vs-all";
  }
  return "ns";
}

std::string modelToDumpString(ModelKind model) {
  switch (model) {
    case ModelKind::kSupervised:
      return "sup";
    case ModelKind::kSkipgram:
      return "sg";
    case ModelKind::kCbow:
      return "cbow";
  }
  return "sg";
}

Args defaultArgsFor(ModelKind model) {
  Args args;
  args.model = model;
  if (model == ModelKind::kSupervised) {
    args.minCount = 1;
    args.minn = 0;
    args.maxn = 0;
    args.lr = 0.1f;
    args.loss = LossKind::kSoftmax;
  }
  return args;
}

std::vector<std::string> splitWhitespace(const std::string& line) {
  std::istringstream input(line);
  std::vector<std::string> tokens;
  std::string token;
  while (input >> token) {
    tokens.push_back(token);
  }
  return tokens;
}

bool startsWith(const std::string& value, const std::string& prefix) {
  return value.size() >= prefix.size() &&
         std::equal(prefix.begin(), prefix.end(), value.begin());
}

std::uint32_t fnv1a(const std::string& value) {
  std::uint32_t hash = 2166136261u;
  for (unsigned char c : value) {
    hash ^= c;
    hash *= 16777619u;
  }
  return hash;
}

std::vector<std::string> subwordStrings(const std::string& token, int minn,
                                        int maxn) {
  std::vector<std::string> result;
  if (minn <= 0 || maxn <= 0) {
    return result;
  }
  const std::string bounded = "<" + token + ">";
  for (std::size_t start = 0; start < bounded.size(); ++start) {
    for (int len = minn; len <= maxn; ++len) {
      if (start + static_cast<std::size_t>(len) <= bounded.size()) {
        result.push_back(bounded.substr(start, len));
      }
    }
  }
  return result;
}

std::vector<int> subwordIds(const std::string& token, int minn, int maxn,
                            int bucket) {
  std::vector<int> ids;
  if (bucket <= 0 || minn <= 0 || maxn <= 0) {
    return ids;
  }
  for (const std::string& ngram : subwordStrings(token, minn, maxn)) {
    ids.push_back(static_cast<int>(fnv1a(ngram) % static_cast<std::uint32_t>(bucket)));
  }
  return ids;
}

std::vector<int> wordNgramIds(const std::vector<std::string>& tokens,
                              int wordNgrams, int bucket) {
  std::vector<int> ids;
  if (bucket <= 0 || wordNgrams <= 1) {
    return ids;
  }
  for (std::size_t i = 0; i < tokens.size(); ++i) {
    std::string current = tokens[i];
    for (int n = 2; n <= wordNgrams && i + static_cast<std::size_t>(n) <= tokens.size();
         ++n) {
      if (n > 2) {
        current.push_back('\x1f');
        current.append(tokens[i + n - 1]);
      } else {
        current = tokens[i] + '\x1f' + tokens[i + 1];
      }
      ids.push_back(static_cast<int>(fnv1a(current) %
                                     static_cast<std::uint32_t>(bucket)));
    }
  }
  return ids;
}

double sigmoid(double x) {
  if (x < -35.0) {
    return 0.0;
  }
  if (x > 35.0) {
    return 1.0;
  }
  return 1.0 / (1.0 + std::exp(-x));
}

double dot(const std::vector<float>& lhs, const std::vector<float>& rhs) {
  double value = 0.0;
  for (std::size_t i = 0; i < lhs.size(); ++i) {
    value += static_cast<double>(lhs[i]) * static_cast<double>(rhs[i]);
  }
  return value;
}

double norm(const std::vector<float>& values) {
  return std::sqrt(dot(values, values));
}

std::vector<float> zeros(int dim) {
  return std::vector<float>(dim, 0.0f);
}

std::vector<float>& ensureBucketVector(Model& model, int id) {
  auto [it, inserted] =
      model.inputBuckets.emplace(id, std::vector<float>(model.args.dim, 0.0f));
  return it->second;
}

const std::vector<float>* findBucketVector(const Model& model, int id) {
  auto it = model.inputBuckets.find(id);
  if (it == model.inputBuckets.end()) {
    return nullptr;
  }
  return &it->second;
}

Components tokenComponents(const Model& model, const std::string& token) {
  Components components;
  auto wordIt = model.dict.wordIndex.find(token);
  if (wordIt != model.dict.wordIndex.end()) {
    components.wordRows.push_back(wordIt->second);
  }
  for (int bucketId :
       subwordIds(token, model.args.minn, model.args.maxn, model.args.bucket)) {
    components.bucketRows.push_back(bucketId);
  }
  return components;
}

Components supervisedLineComponents(const Model& model,
                                    const std::vector<std::string>& tokens) {
  Components components;
  for (const std::string& token : tokens) {
    Components tokenParts = tokenComponents(model, token);
    components.wordRows.insert(components.wordRows.end(), tokenParts.wordRows.begin(),
                               tokenParts.wordRows.end());
    components.bucketRows.insert(components.bucketRows.end(), tokenParts.bucketRows.begin(),
                                 tokenParts.bucketRows.end());
  }
  for (int bucketId :
       wordNgramIds(tokens, model.args.wordNgrams, model.args.bucket)) {
    components.bucketRows.push_back(bucketId);
  }
  return components;
}

std::vector<float> averageInput(const Model& model, const Components& components) {
  std::vector<float> hidden(model.args.dim, 0.0f);
  const double count = static_cast<double>(components.size());
  if (count == 0.0) {
    return hidden;
  }
  for (int index : components.wordRows) {
    const std::vector<float>& values = model.inputWords[index];
    for (int d = 0; d < model.args.dim; ++d) {
      hidden[d] += values[d];
    }
  }
  for (int index : components.bucketRows) {
    const std::vector<float>* values = findBucketVector(model, index);
    if (values == nullptr) {
      continue;
    }
    for (int d = 0; d < model.args.dim; ++d) {
      hidden[d] += (*values)[d];
    }
  }
  for (float& value : hidden) {
    value = static_cast<float>(value / count);
  }
  return hidden;
}

void applyInputGradient(Model& model, const Components& components,
                        const std::vector<float>& grad) {
  const double count = static_cast<double>(components.size());
  if (count == 0.0) {
    return;
  }
  const float scale = static_cast<float>(1.0 / count);
  for (int index : components.wordRows) {
    std::vector<float>& values = model.inputWords[index];
    for (int d = 0; d < model.args.dim; ++d) {
      values[d] += grad[d] * scale;
    }
  }
  for (int index : components.bucketRows) {
    std::vector<float>& values = ensureBucketVector(model, index);
    for (int d = 0; d < model.args.dim; ++d) {
      values[d] += grad[d] * scale;
    }
  }
}

std::vector<float> wordVector(const Model& model, const std::string& token) {
  return averageInput(model, tokenComponents(model, token));
}

