std::optional<LossKind> parseLoss(const std::string& value) {
  if (value == "ns") {
    return LossKind::kNs;
  }
  if (value == "hs") {
    return LossKind::kHs;
  }
  if (value == "softmax") {
    return LossKind::kSoftmax;
  }
  if (value == "one-vs-all") {
    return LossKind::kOneVsAll;
  }
  return std::nullopt;
}

std::optional<ParseError> parseTrainingArgs(const std::vector<std::string>& argv,
                                            Args& args) {
  const std::unordered_set<std::string> boolFlags = {"-saveOutput", "-retrain",
                                                     "-qnorm", "-qout"};
  for (std::size_t i = 0; i < argv.size(); ++i) {
    const std::string& token = argv[i];
    if (token.empty() || token[0] != '-') {
      return ParseError{"Provided argument without a dash! Usage:"};
    }
    if (boolFlags.count(token) != 0) {
      if (token == "-saveOutput") {
        args.saveOutput = true;
      } else if (token == "-retrain") {
        args.retrain = true;
      } else if (token == "-qnorm") {
        args.qnorm = true;
      } else if (token == "-qout") {
        args.qout = true;
      }
      continue;
    }
    if (i + 1 >= argv.size()) {
      return ParseError{token + " is missing an argument"};
    }
    const std::string value = argv[++i];
    if (token == "-input") {
      args.input = value;
    } else if (token == "-output") {
      args.output = value;
    } else if (token == "-verbose") {
      args.verbose = std::stoi(value);
    } else if (token == "-minCount") {
      args.minCount = std::stoi(value);
    } else if (token == "-minCountLabel") {
      args.minCountLabel = std::stoi(value);
    } else if (token == "-wordNgrams") {
      args.wordNgrams = std::stoi(value);
    } else if (token == "-bucket") {
      args.bucket = std::stoi(value);
    } else if (token == "-minn") {
      args.minn = std::stoi(value);
    } else if (token == "-maxn") {
      args.maxn = std::stoi(value);
    } else if (token == "-t") {
      args.t = std::stof(value);
    } else if (token == "-label") {
      args.label = value;
    } else if (token == "-lr") {
      args.lr = std::stof(value);
    } else if (token == "-lrUpdateRate") {
      args.lrUpdateRate = std::stoi(value);
    } else if (token == "-dim") {
      args.dim = std::stoi(value);
    } else if (token == "-ws") {
      args.ws = std::stoi(value);
    } else if (token == "-epoch") {
      args.epoch = std::stoi(value);
    } else if (token == "-neg") {
      args.neg = std::stoi(value);
    } else if (token == "-loss") {
      std::optional<LossKind> parsed = parseLoss(value);
      if (!parsed.has_value()) {
        return ParseError{"Unknown loss: " + value};
      }
      args.loss = *parsed;
    } else if (token == "-thread") {
      args.thread = std::stoi(value);
    } else if (token == "-pretrainedVectors") {
      args.pretrainedVectors = value;
    } else if (token == "-seed") {
      args.seed = std::stoi(value);
    } else if (token == "-autotune-validation") {
      args.autotuneValidation = value;
    } else if (token == "-autotune-metric") {
      args.autotuneMetric = value;
    } else if (token == "-autotune-predictions") {
      args.autotunePredictions = std::stoi(value);
    } else if (token == "-autotune-duration") {
      args.autotuneDuration = std::stoi(value);
    } else if (token == "-autotune-modelsize") {
      args.autotuneModelSize = value;
    } else if (token == "-cutoff") {
      args.cutoff = std::stoi(value);
    } else if (token == "-dsub") {
      args.dsub = std::stoi(value);
    } else {
      return ParseError{"Unknown argument: " + token};
    }
  }
  return std::nullopt;
}

