}

Corpus readCorpus(const std::string& path, bool supervised,
                  const std::string& labelPrefix) {
  std::ifstream input(path);
  if (!input) {
    throwCannotOpenForTraining(path);
  }
  Corpus corpus;
  std::string line;
  while (std::getline(input, line)) {
    Example example;
    for (const std::string& token : splitWhitespace(line)) {
      if (supervised && startsWith(token, labelPrefix)) {
        example.labelTokens.push_back(token);
      } else {
        example.wordTokens.push_back(token);
      }
    }
    corpus.examples.push_back(std::move(example));
    ++corpus.totalLines;
  }
  return corpus;
}

Dictionary buildDictionary(Corpus& corpus, const Args& args, bool supervised) {
  Dictionary dict;
  std::unordered_map<std::string, std::int64_t> wordCounts;
  std::unordered_map<std::string, std::int64_t> labelCounts;
  std::vector<std::string> wordOrder;
  std::vector<std::string> labelOrder;
  auto rememberWord = [&](const std::string& token) {
    if (wordCounts.emplace(token, 0).second) {
      wordOrder.push_back(token);
    }
    ++wordCounts[token];
  };
  auto rememberLabel = [&](const std::string& token) {
    if (labelCounts.emplace(token, 0).second) {
      labelOrder.push_back(token);
    }
    ++labelCounts[token];
  };

  for (Example& example : corpus.examples) {
    for (const std::string& token : example.wordTokens) {
      rememberWord(token);
    }
    if (supervised) {
      for (const std::string& token : example.labelTokens) {
        rememberLabel(token);
      }
    }
  }

  if (corpus.totalLines > 0) {
    wordCounts["</s>"] = corpus.totalLines;
  }

  auto addWord = [&](const std::string& token) {
    Entry entry;
    entry.token = token;
    entry.count = wordCounts[token];
    entry.isLabel = false;
    dict.wordIndex[token] = dict.numWords++;
    dict.entries.push_back(entry);
  };

  if (wordCounts["</s>"] >= args.minCount) {
    addWord("</s>");
  }
  for (const std::string& token : wordOrder) {
    if (wordCounts[token] >= args.minCount) {
      addWord(token);
    }
  }
  for (const std::string& token : labelOrder) {
    if (labelCounts[token] >= args.minCountLabel) {
      Entry entry;
      entry.token = token;
      entry.count = labelCounts[token];
      entry.isLabel = true;
      dict.labelIndex[token] = dict.numLabels++;
      dict.entries.push_back(entry);
    }
  }

  for (Example& example : corpus.examples) {
    for (const std::string& token : example.wordTokens) {
      auto it = dict.wordIndex.find(token);
      if (it != dict.wordIndex.end()) {
        example.wordIds.push_back(it->second);
      }
    }
    for (const std::string& token : example.labelTokens) {
      auto it = dict.labelIndex.find(token);
      if (it != dict.labelIndex.end()) {
        example.labelIds.push_back(it->second);
      }
    }
  }

  return dict;
}

std::vector<float> randomVector(int dim, std::minstd_rand& rng) {
  std::uniform_real_distribution<float> dist(-0.1f, 0.1f);
  std::vector<float> values(dim, 0.0f);
  for (float& value : values) {
    value = dist(rng) / static_cast<float>(dim);
  }
  return values;
}

void initializeModel(Model& model) {
  std::minstd_rand rng(static_cast<std::uint32_t>(model.args.seed));
  model.inputWords.assign(model.dict.numWords, std::vector<float>(model.args.dim, 0.0f));
  for (std::vector<float>& row : model.inputWords) {
    row = randomVector(model.args.dim, rng);
  }
  const int outputRows = model.args.model == ModelKind::kSupervised ? model.dict.numLabels
                                                                    : model.dict.numWords;
  model.outputRows.assign(outputRows, std::vector<float>(model.args.dim, 0.0f));
}

std::vector<float> softmax(const std::vector<double>& scores) {
  std::vector<float> probs(scores.size(), 0.0f);
  if (scores.empty()) {
    return probs;
  }
  const double maxScore =
      *std::max_element(scores.begin(), scores.end());
  double sum = 0.0;
  for (std::size_t i = 0; i < scores.size(); ++i) {
    probs[i] = static_cast<float>(std::exp(scores[i] - maxScore));
    sum += probs[i];
  }
  if (sum == 0.0) {
    return probs;
  }
  for (float& prob : probs) {
    prob = static_cast<float>(prob / sum);
  }
  return probs;
}

double trainSupervised(Model& model, const Corpus& corpus) {
  if (model.dict.numLabels == 0) {
    return -std::numeric_limits<double>::quiet_NaN();
  }
  double totalLoss = 0.0;
  std::size_t lossCount = 0;
  for (int epoch = 0; epoch < model.args.epoch; ++epoch) {
    for (const Example& example : corpus.examples) {
      if (example.wordIds.empty() || example.labelIds.empty()) {
        continue;
      }
      Components components = supervisedLineComponents(model, example.wordTokens);
      if (components.size() == 0) {
        continue;
      }
      std::vector<float> hidden = averageInput(model, components);
      if (model.args.loss == LossKind::kOneVsAll) {
        std::vector<float> grad(model.args.dim, 0.0f);
        std::unordered_set<int> positives(example.labelIds.begin(), example.labelIds.end());
        for (int label = 0; label < model.dict.numLabels; ++label) {
          const double score = dot(model.outputRows[label], hidden);
          const double prob = sigmoid(score);
          const double target = positives.count(label) == 0 ? 0.0 : 1.0;
          const double diff = (target - prob) * model.args.lr;
          for (int d = 0; d < model.args.dim; ++d) {
            grad[d] += static_cast<float>(diff * model.outputRows[label][d]);
            model.outputRows[label][d] += static_cast<float>(diff * hidden[d]);
          }
          const double clipped = std::clamp(prob, 1e-12, 1.0 - 1e-12);
          totalLoss += -(target * std::log(clipped) +
                         (1.0 - target) * std::log(1.0 - clipped));
        }
        ++lossCount;
        applyInputGradient(model, components, grad);
        continue;
      }

      std::vector<double> scores(model.dict.numLabels, 0.0);
      for (int label = 0; label < model.dict.numLabels; ++label) {
        scores[label] = dot(model.outputRows[label], hidden);
      }
      std::vector<float> probs = softmax(scores);
      std::vector<float> grad(model.args.dim, 0.0f);
      for (int label = 0; label < model.dict.numLabels; ++label) {
        const bool positive = std::find(example.labelIds.begin(), example.labelIds.end(),
                                        label) != example.labelIds.end();
        const float target = positive ? 1.0f / example.labelIds.size() : 0.0f;
        const float diff = (target - probs[label]) * model.args.lr;
        for (int d = 0; d < model.args.dim; ++d) {
          grad[d] += diff * model.outputRows[label][d];
          model.outputRows[label][d] += diff * hidden[d];
        }
      }
      for (int labelId : example.labelIds) {
        totalLoss -= std::log(std::max(1e-12f, probs[labelId])) /
                     static_cast<double>(example.labelIds.size());
      }
      ++lossCount;
      applyInputGradient(model, components, grad);
    }
  }
  if (lossCount == 0) {
    return -std::numeric_limits<double>::quiet_NaN();
  }
  return totalLoss / static_cast<double>(lossCount);
}

std::vector<double> buildUnigramTable(const Dictionary& dict) {
  std::vector<double> weights(dict.numWords, 1.0);
  for (int i = 0; i < dict.numWords; ++i) {
    weights[i] = std::pow(static_cast<double>(dict.entries[i].count), 0.75);
  }
  return weights;
}

void sgnsUpdate(Model& model, const Components& components, int outputIndex,
                float label, float lr) {
  if (components.size() == 0 || outputIndex < 0 ||
      outputIndex >= static_cast<int>(model.outputRows.size())) {
    return;
  }
  std::vector<float> hidden = averageInput(model, components);
  const double score = dot(model.outputRows[outputIndex], hidden);
  const float diff = static_cast<float>((label - sigmoid(score)) * lr);
  std::vector<float> grad(model.args.dim, 0.0f);
  for (int d = 0; d < model.args.dim; ++d) {
    grad[d] += diff * model.outputRows[outputIndex][d];
    model.outputRows[outputIndex][d] += diff * hidden[d];
  }
  applyInputGradient(model, components, grad);
}

void trainSkipgram(Model& model, const Corpus& corpus) {
  std::minstd_rand rng(static_cast<std::uint32_t>(model.args.seed));
  std::discrete_distribution<int> negSampler(buildUnigramTable(model.dict).begin(),
                                             buildUnigramTable(model.dict).end());
  for (int epoch = 0; epoch < model.args.epoch; ++epoch) {
    for (const Example& example : corpus.examples) {
      for (std::size_t i = 0; i < example.wordTokens.size(); ++i) {
        const int targetId = example.wordIds[i];
        Components target = tokenComponents(model, example.wordTokens[i]);
        const std::size_t begin = i > static_cast<std::size_t>(model.args.ws)
                                      ? i - static_cast<std::size_t>(model.args.ws)
                                      : 0;
        const std::size_t end =
            std::min(example.wordTokens.size(), i + static_cast<std::size_t>(model.args.ws) + 1);
        for (std::size_t j = begin; j < end; ++j) {
          if (i == j) {
            continue;
          }
          const int contextId = example.wordIds[j];
          if (model.args.loss == LossKind::kSoftmax || model.args.loss == LossKind::kHs) {
            std::vector<float> hidden = averageInput(model, target);
            std::vector<double> scores(model.dict.numWords, 0.0);
            for (int word = 0; word < model.dict.numWords; ++word) {
              scores[word] = dot(model.outputRows[word], hidden);
            }
            std::vector<float> probs = softmax(scores);
            std::vector<float> grad(model.args.dim, 0.0f);
            for (int word = 0; word < model.dict.numWords; ++word) {
              const float targetProb = word == contextId ? 1.0f : 0.0f;
              const float diff = (targetProb - probs[word]) * model.args.lr;
              for (int d = 0; d < model.args.dim; ++d) {
                grad[d] += diff * model.outputRows[word][d];
                model.outputRows[word][d] += diff * hidden[d];
              }
            }
            applyInputGradient(model, target, grad);
          } else {
            sgnsUpdate(model, target, contextId, 1.0f, model.args.lr);
            for (int n = 0; n < model.args.neg; ++n) {
              sgnsUpdate(model, target, negSampler(rng), 0.0f, model.args.lr);
            }
          }
        }
        (void)targetId;
      }
    }
  }
}

void trainCbow(Model& model, const Corpus& corpus) {
  std::minstd_rand rng(static_cast<std::uint32_t>(model.args.seed));
  std::discrete_distribution<int> negSampler(buildUnigramTable(model.dict).begin(),
                                             buildUnigramTable(model.dict).end());
  for (int epoch = 0; epoch < model.args.epoch; ++epoch) {
    for (const Example& example : corpus.examples) {
      for (std::size_t i = 0; i < example.wordTokens.size(); ++i) {
        Components context;
        const std::size_t begin = i > static_cast<std::size_t>(model.args.ws)
                                      ? i - static_cast<std::size_t>(model.args.ws)
                                      : 0;
        const std::size_t end =
            std::min(example.wordTokens.size(), i + static_cast<std::size_t>(model.args.ws) + 1);
        for (std::size_t j = begin; j < end; ++j) {
          if (i == j) {
            continue;
          }
          Components token = tokenComponents(model, example.wordTokens[j]);
          context.wordRows.insert(context.wordRows.end(), token.wordRows.begin(),
                                  token.wordRows.end());
          context.bucketRows.insert(context.bucketRows.end(), token.bucketRows.begin(),
                                    token.bucketRows.end());
        }
        if (context.size() == 0) {
          continue;
        }
        const int targetId = example.wordIds[i];
        if (model.args.loss == LossKind::kSoftmax || model.args.loss == LossKind::kHs) {
          std::vector<float> hidden = averageInput(model, context);
          std::vector<double> scores(model.dict.numWords, 0.0);
          for (int word = 0; word < model.dict.numWords; ++word) {
            scores[word] = dot(model.outputRows[word], hidden);
          }
          std::vector<float> probs = softmax(scores);
          std::vector<float> grad(model.args.dim, 0.0f);
          for (int word = 0; word < model.dict.numWords; ++word) {
            const float targetProb = word == targetId ? 1.0f : 0.0f;
            const float diff = (targetProb - probs[word]) * model.args.lr;
            for (int d = 0; d < model.args.dim; ++d) {
              grad[d] += diff * model.outputRows[word][d];
              model.outputRows[word][d] += diff * hidden[d];
            }
          }
          applyInputGradient(model, context, grad);
        } else {
          sgnsUpdate(model, context, targetId, 1.0f, model.args.lr);
          for (int n = 0; n < model.args.neg; ++n) {
            sgnsUpdate(model, context, negSampler(rng), 0.0f, model.args.lr);
          }
        }
      }
    }
  }
}

void printTrainingProgress(const Args& args, const Dictionary& dict, double loss,
                           std::int64_t totalWords, double seconds) {
  std::cerr << "\rRead " << static_cast<long long>(totalWords / 1000000) << "M words\n";
  std::cerr << "Number of words:  " << dict.numWords << "\n";
  std::cerr << "Number of labels: " << dict.numLabels << "\n";
  const double rate =
      seconds > 0.0 ? static_cast<double>(totalWords) / seconds : static_cast<double>(totalWords);
  std::cerr << "\rProgress: 100.0% words/sec/thread: " << std::setw(8)
            << static_cast<long long>(rate) << " lr:  " << std::fixed
            << std::setprecision(6) << 0.0 << " avg.loss: " << std::setw(9)
            << std::defaultfloat << loss << " ETA:   0h 0m 0s\n";
  (void)args;
}

template <typename T>
void writePod(std::ostream& out, const T& value) {
  out.write(reinterpret_cast<const char*>(&value), sizeof(T));
}

template <typename T>
void readPod(std::istream& in, T& value) {
  in.read(reinterpret_cast<char*>(&value), sizeof(T));
}

void writeString(std::ostream& out, const std::string& value) {
  std::uint32_t size = static_cast<std::uint32_t>(value.size());
  writePod(out, size);
  out.write(value.data(), static_cast<std::streamsize>(value.size()));
}

std::string readString(std::istream& in) {
  std::uint32_t size = 0;
  readPod(in, size);
  std::string value(size, '\0');
  in.read(value.data(), static_cast<std::streamsize>(size));
  return value;
}

void saveModel(const Model& model, const std::string& path) {
  std::ofstream out(path, std::ios::binary);
  if (!out) {
    throwCannotOpenForSaving(path);
  }
  out.write(kMagic, 8);
  std::uint32_t version = 1;
  writePod(out, version);
  writeString(out, modelToDumpString(model.args.model));
  writeString(out, lossToString(model.args.loss));
  writePod(out, model.quantized);
  writePod(out, model.args.verbose);
  writePod(out, model.args.minCount);
  writePod(out, model.args.minCountLabel);
  writePod(out, model.args.wordNgrams);
  writePod(out, model.args.bucket);
  writePod(out, model.args.minn);
  writePod(out, model.args.maxn);
  writePod(out, model.args.t);
  writeString(out, model.args.label);
  writePod(out, model.args.lr);
  writePod(out, model.args.lrUpdateRate);
  writePod(out, model.args.dim);
  writePod(out, model.args.ws);
  writePod(out, model.args.epoch);
  writePod(out, model.args.neg);
  writePod(out, model.args.thread);
  writeString(out, model.args.pretrainedVectors);
  writePod(out, model.args.saveOutput);
  writePod(out, model.args.seed);
  writeString(out, model.args.autotuneValidation);
  writeString(out, model.args.autotuneMetric);
  writePod(out, model.args.autotunePredictions);
  writePod(out, model.args.autotuneDuration);
  writeString(out, model.args.autotuneModelSize);
  writePod(out, model.args.cutoff);
  writePod(out, model.args.retrain);
  writePod(out, model.args.qnorm);
  writePod(out, model.args.qout);
  writePod(out, model.args.dsub);

  writePod(out, model.dict.numWords);
  writePod(out, model.dict.numLabels);
  std::uint32_t entryCount = static_cast<std::uint32_t>(model.dict.entries.size());
  writePod(out, entryCount);
  for (const Entry& entry : model.dict.entries) {
    writeString(out, entry.token);
    writePod(out, entry.count);
    writePod(out, entry.isLabel);
  }

  std::uint32_t inputRows = static_cast<std::uint32_t>(model.inputWords.size());
  writePod(out, inputRows);
  for (const std::vector<float>& row : model.inputWords) {
    out.write(reinterpret_cast<const char*>(row.data()),
              static_cast<std::streamsize>(row.size() * sizeof(float)));
  }

  std::uint32_t outputRows = static_cast<std::uint32_t>(model.outputRows.size());
  writePod(out, outputRows);
  for (const std::vector<float>& row : model.outputRows) {
    out.write(reinterpret_cast<const char*>(row.data()),
              static_cast<std::streamsize>(row.size() * sizeof(float)));
  }

  std::uint32_t bucketCount = static_cast<std::uint32_t>(model.inputBuckets.size());
  writePod(out, bucketCount);
  for (const auto& [bucketId, row] : model.inputBuckets) {
    writePod(out, bucketId);
    out.write(reinterpret_cast<const char*>(row.data()),
              static_cast<std::streamsize>(row.size() * sizeof(float)));
  }
}

Model loadModel(const std::string& path) {
  std::ifstream in(path, std::ios::binary);
  if (!in) {
    throwCannotOpenForLoading(path);
  }
  char magic[8];
  in.read(magic, 8);
  if (!in || std::string(magic, 8) != std::string(kMagic, 8)) {
    throwCannotOpenForLoading(path);
  }
  Model model;
  std::uint32_t version = 0;
  readPod(in, version);
  (void)version;
  const std::string modelName = readString(in);
  const std::string lossName = readString(in);
  if (modelName == "sup") {
    model.args.model = ModelKind::kSupervised;
  } else if (modelName == "cbow") {
    model.args.model = ModelKind::kCbow;
  } else {
    model.args.model = ModelKind::kSkipgram;
  }
  model.args.loss = parseLoss(lossName).value_or(LossKind::kNs);
  readPod(in, model.quantized);
  readPod(in, model.args.verbose);
  readPod(in, model.args.minCount);
  readPod(in, model.args.minCountLabel);
  readPod(in, model.args.wordNgrams);
  readPod(in, model.args.bucket);
  readPod(in, model.args.minn);
  readPod(in, model.args.maxn);
  readPod(in, model.args.t);
  model.args.label = readString(in);
  readPod(in, model.args.lr);
  readPod(in, model.args.lrUpdateRate);
  readPod(in, model.args.dim);
  readPod(in, model.args.ws);
  readPod(in, model.args.epoch);
  readPod(in, model.args.neg);
  readPod(in, model.args.thread);
  model.args.pretrainedVectors = readString(in);
  readPod(in, model.args.saveOutput);
  readPod(in, model.args.seed);
  model.args.autotuneValidation = readString(in);
  model.args.autotuneMetric = readString(in);
  readPod(in, model.args.autotunePredictions);
  readPod(in, model.args.autotuneDuration);
  model.args.autotuneModelSize = readString(in);
  readPod(in, model.args.cutoff);
  readPod(in, model.args.retrain);
  readPod(in, model.args.qnorm);
  readPod(in, model.args.qout);
  readPod(in, model.args.dsub);

  readPod(in, model.dict.numWords);
  readPod(in, model.dict.numLabels);
  std::uint32_t entryCount = 0;
  readPod(in, entryCount);
  model.dict.entries.resize(entryCount);
  for (std::uint32_t i = 0; i < entryCount; ++i) {
    model.dict.entries[i].token = readString(in);
    readPod(in, model.dict.entries[i].count);
    readPod(in, model.dict.entries[i].isLabel);
    if (model.dict.entries[i].isLabel) {
      model.dict.labelIndex[model.dict.entries[i].token] =
          static_cast<int>(i) - model.dict.numWords;
    } else if (static_cast<int>(i) < model.dict.numWords) {
      model.dict.wordIndex[model.dict.entries[i].token] = static_cast<int>(i);
    }
  }

  std::uint32_t inputRows = 0;
  readPod(in, inputRows);
  model.inputWords.assign(inputRows, std::vector<float>(model.args.dim, 0.0f));
  for (std::uint32_t row = 0; row < inputRows; ++row) {
    in.read(reinterpret_cast<char*>(model.inputWords[row].data()),
            static_cast<std::streamsize>(model.args.dim * sizeof(float)));
  }

  std::uint32_t outputRows = 0;
  readPod(in, outputRows);
  model.outputRows.assign(outputRows, std::vector<float>(model.args.dim, 0.0f));
  for (std::uint32_t row = 0; row < outputRows; ++row) {
    in.read(reinterpret_cast<char*>(model.outputRows[row].data()),
            static_cast<std::streamsize>(model.args.dim * sizeof(float)));
  }

  std::uint32_t bucketCount = 0;
  readPod(in, bucketCount);
  for (std::uint32_t i = 0; i < bucketCount; ++i) {
    int bucketId = 0;
    readPod(in, bucketId);
    std::vector<float> row(model.args.dim, 0.0f);
    in.read(reinterpret_cast<char*>(row.data()),
            static_cast<std::streamsize>(model.args.dim * sizeof(float)));
    model.inputBuckets.emplace(bucketId, std::move(row));
  }

  if (!in) {
    throwCannotOpenForLoading(path);
  }
  return model;
}

void saveVec(const Model& model, const std::string& path) {
  std::ofstream out(path);
  if (!out) {
    throwCannotOpenForSaving(path);
  }
  out << model.dict.numWords << ' ' << model.args.dim << '\n';
  for (int i = 0; i < model.dict.numWords; ++i) {
    out << model.dict.entries[i].token << ' ';
    const std::vector<float> values = wordVector(model, model.dict.entries[i].token);
    for (float value : values) {
      out << value << ' ';
    }
    out << '\n';
  }
}

std::string modelPathForOutput(const std::string& base) {
  return base + ".bin";
}

std::string vecPathForOutput(const std::string& base) {
  return base + ".vec";
}

std::string ftzPathForOutput(const std::string& base) {
  return base + ".ftz";
}

std::vector<Prediction> predictLine(const Model& model,
                                    const std::vector<std::string>& tokens) {
  std::vector<Prediction> predictions;
  if (model.dict.numLabels == 0) {
    return predictions;
  }
  Components components = supervisedLineComponents(model, tokens);
  std::vector<float> hidden = averageInput(model, components);
  if (model.args.loss == LossKind::kOneVsAll) {
    predictions.reserve(model.dict.numLabels);
    for (int label = 0; label < model.dict.numLabels; ++label) {
      predictions.push_back({label, sigmoid(dot(model.outputRows[label], hidden))});
    }
  } else {
    std::vector<double> scores(model.dict.numLabels, 0.0);
    for (int label = 0; label < model.dict.numLabels; ++label) {
      scores[label] = dot(model.outputRows[label], hidden);
    }
    std::vector<float> probs = softmax(scores);
    predictions.reserve(model.dict.numLabels);
    for (int label = 0; label < model.dict.numLabels; ++label) {
      predictions.push_back({label, probs[label]});
    }
  }
  std::stable_sort(predictions.begin(), predictions.end(),
                   [](const Prediction& lhs, const Prediction& rhs) {
                     return lhs.score > rhs.score;
                   });
  return predictions;
}

