std::vector<std::string> extractTrueLabels(const Model& model,
                                           const std::vector<std::string>& tokens,
                                           std::vector<std::string>& words) {
  std::vector<std::string> labels;
  for (const std::string& token : tokens) {
    if (startsWith(token, model.args.label)) {
      labels.push_back(token);
    } else {
      words.push_back(token);
    }
  }
  return labels;
}

int runTrainingCommand(ModelKind kind, const std::vector<std::string>& argv) {
  Args args = defaultArgsFor(kind);
  if (argv.empty()) {
    if (kind == ModelKind::kSupervised || kind == ModelKind::kSkipgram ||
        kind == ModelKind::kCbow) {
      std::cerr << "Empty input or output path.\n\n";
      printTrainingHelp(args, std::cerr);
      return 1;
    }
  }
  std::optional<ParseError> error = parseTrainingArgs(argv, args);
  if (error.has_value()) {
    std::cerr << error->message << "\n\n";
    printTrainingHelp(args, std::cerr);
    return 1;
  }
  if (args.input.empty() || args.output.empty()) {
    std::cerr << "Empty input or output path.\n\n";
    printTrainingHelp(args, std::cerr);
    return 1;
  }

  const bool supervised = kind == ModelKind::kSupervised;
  const auto start = std::chrono::steady_clock::now();
  Corpus corpus = readCorpus(args.input, supervised, args.label);
  Dictionary dict = buildDictionary(corpus, args, supervised);
  const std::int64_t totalWords = [&]() {
    std::int64_t words = 0;
    for (const Example& example : corpus.examples) {
      words += static_cast<std::int64_t>(example.wordIds.size());
    }
    return words;
  }();

  Model model;
  model.args = args;
  model.dict = std::move(dict);
  initializeModel(model);
  if (model.dict.numWords == 0) {
    const auto end = std::chrono::steady_clock::now();
    const double seconds =
        std::chrono::duration<double>(end - start).count();
    printTrainingProgress(args, model.dict, -std::numeric_limits<double>::quiet_NaN(),
                          totalWords, seconds);
    throw std::invalid_argument("Empty vocabulary. Try a smaller -minCount value.");
  }

  double loss = -std::numeric_limits<double>::quiet_NaN();
  if (kind == ModelKind::kSupervised) {
    loss = trainSupervised(model, corpus);
  } else if (kind == ModelKind::kSkipgram) {
    trainSkipgram(model, corpus);
  } else {
    trainCbow(model, corpus);
  }

  saveModel(model, modelPathForOutput(args.output));
  saveVec(model, vecPathForOutput(args.output));

  const auto end = std::chrono::steady_clock::now();
  const double seconds = std::chrono::duration<double>(end - start).count();
  printTrainingProgress(args, model.dict, loss, totalWords, seconds);
  return 0;
}

int runQuantize(const std::vector<std::string>& argv) {
  Args args = defaultArgsFor(ModelKind::kSkipgram);
  if (argv.empty()) {
    std::cerr << "usage: fasttext quantize <args>\n\n";
    printTrainingHelp(args, std::cerr);
    return 1;
  }
  std::optional<ParseError> error = parseTrainingArgs(argv, args);
  if (error.has_value()) {
    std::cerr << error->message << "\n\n";
    printTrainingHelp(args, std::cerr);
    return 1;
  }
  if (args.input.empty() || args.output.empty()) {
    std::cerr << "Empty input or output path.\n\n";
    printTrainingHelp(args, std::cerr);
    return 1;
  }
  Model model = loadModel(modelPathForOutput(args.output));
  if (model.dict.numWords < 256) {
    throw std::invalid_argument(
        "Matrix too small for quantization, must have at least 256 rows");
  }
  model.quantized = true;
  saveModel(model, ftzPathForOutput(args.output));
  return 0;
}

int runPredictLike(const std::vector<std::string>& argv, bool withProbabilities) {
  if (argv.size() < 2) {
    std::cerr << "usage: fasttext predict[-prob] <model> <test-data> [<k>] [<th>]\n\n";
    std::cerr << "  <model>      model filename\n";
    std::cerr << "  <test-data>  test data filename (if -, read from stdin)\n";
    std::cerr << "  <k>          (optional; 1 by default) predict top k labels\n";
    std::cerr << "  <th>         (optional; 0.0 by default) probability threshold\n";
    return 1;
  }
  const int k = argv.size() >= 3 ? std::stoi(argv[2]) : 1;
  const float threshold = argv.size() >= 4 ? std::stof(argv[3]) : 0.0f;
  Model model = loadModel(argv[0]);

  std::unique_ptr<std::istream> owned;
  std::istream* input = nullptr;
  if (argv[1] == "-") {
    input = &std::cin;
  } else {
    auto file = std::make_unique<std::ifstream>(argv[1]);
    if (!*file) {
      throwCannotOpenForLoading(argv[1]);
    }
    input = file.get();
    owned = std::move(file);
  }

  std::string line;
  while (std::getline(*input, line)) {
    std::vector<std::string> words;
    const std::vector<std::string> trueLabels =
        extractTrueLabels(model, splitWhitespace(line), words);
    (void)trueLabels;
    const std::vector<Prediction> predictions = predictLine(model, words);
    bool first = true;
    int emitted = 0;
    for (const Prediction& prediction : predictions) {
      if (prediction.score < threshold) {
        continue;
      }
      if (emitted >= k) {
        break;
      }
      if (!first) {
        std::cout << ' ';
      }
      first = false;
      const std::string& label =
          model.dict.entries[model.dict.numWords + prediction.labelIndex].token;
      if (withProbabilities) {
        std::cout << label << ' ' << prediction.score;
      } else {
        std::cout << label;
      }
      ++emitted;
    }
    std::cout << '\n';
  }
  return 0;
}

int runTest(const std::vector<std::string>& argv, bool byLabel) {
  if (argv.size() < 2) {
    if (byLabel) {
      std::cerr << "usage: fasttext test-label <model> <test-data> [<k>] [<th>]\n\n";
      std::cerr << "  <model>      model filename\n";
      std::cerr << "  <test-data>  test data filename\n";
      std::cerr << "  <k>          (optional; 1 by default) predict top k labels\n";
      std::cerr << "  <th>         (optional; 0.0 by default) probability threshold\n";
    } else {
      std::cerr << "usage: fasttext test <model> <test-data> [<k>] [<th>]\n\n";
      std::cerr << "  <model>      model filename\n";
      std::cerr << "  <test-data>  test data filename (if -, read from stdin)\n";
      std::cerr << "  <k>          (optional; 1 by default) predict top k labels\n";
      std::cerr << "  <th>         (optional; 0.0 by default) probability threshold\n";
    }
    return 1;
  }
  const int k = argv.size() >= 3 ? std::stoi(argv[2]) : 1;
  const float threshold = argv.size() >= 4 ? std::stof(argv[3]) : 0.0f;
  Model model = loadModel(argv[0]);

  std::unique_ptr<std::istream> owned;
  std::istream* input = nullptr;
  if (argv[1] == "-") {
    static std::istringstream empty;
    empty.clear();
    empty.str("");
    input = &empty;
  } else {
    auto file = std::make_unique<std::ifstream>(argv[1]);
    if (!*file) {
      throwCannotOpenForLoading(argv[1]);
    }
    input = file.get();
    owned = std::move(file);
  }

  int examples = 0;
  int predictedCount = 0;
  int trueCount = 0;
  int hitCount = 0;
  std::vector<int> perLabelActual(model.dict.numLabels, 0);
  std::vector<int> perLabelPredicted(model.dict.numLabels, 0);
  std::vector<int> perLabelCorrect(model.dict.numLabels, 0);

  std::string line;
  while (std::getline(*input, line)) {
    std::vector<std::string> words;
    const std::vector<std::string> labels =
        extractTrueLabels(model, splitWhitespace(line), words);
    if (labels.empty()) {
      continue;
    }
    ++examples;
    std::unordered_set<std::string> labelSet(labels.begin(), labels.end());
    trueCount += static_cast<int>(labels.size());
    for (const std::string& label : labels) {
      auto it = model.dict.labelIndex.find(label);
      if (it != model.dict.labelIndex.end()) {
        ++perLabelActual[it->second];
      }
    }
    const std::vector<Prediction> predictions = predictLine(model, words);
    int emitted = 0;
    for (const Prediction& prediction : predictions) {
      if (prediction.score < threshold) {
        continue;
      }
      if (emitted >= k) {
        break;
      }
      ++emitted;
      ++predictedCount;
      ++perLabelPredicted[prediction.labelIndex];
      const std::string& label =
          model.dict.entries[model.dict.numWords + prediction.labelIndex].token;
      if (labelSet.count(label) != 0) {
        ++hitCount;
        ++perLabelCorrect[prediction.labelIndex];
      }
    }
  }

  const double precision =
      predictedCount == 0 ? std::numeric_limits<double>::quiet_NaN()
                          : static_cast<double>(hitCount) / predictedCount;
  const double recall =
      trueCount == 0 ? std::numeric_limits<double>::quiet_NaN()
                     : static_cast<double>(hitCount) / trueCount;

  if (byLabel) {
    for (int label = 0; label < model.dict.numLabels; ++label) {
      const auto p =
          safeDivide(static_cast<double>(perLabelCorrect[label]), perLabelPredicted[label]);
      const auto r =
          safeDivide(static_cast<double>(perLabelCorrect[label]), perLabelActual[label]);
      std::optional<double> f1;
      if (p.has_value() && r.has_value() && (*p + *r) > 0.0) {
        f1 = 2.0 * (*p) * (*r) / (*p + *r);
      } else if (perLabelActual[label] > 0 || perLabelPredicted[label] > 0) {
        f1 = 0.0;
      }
      std::cout << "F1-Score : " << formatSix(f1)
                << "  Precision : " << formatSix(p)
                << "  Recall : " << formatSix(r) << "   "
                << model.dict.entries[model.dict.numWords + label].token << '\n';
    }
    printMetricsLineTestLabel(examples, k, precision, recall);
  } else {
    printMetricsLineTest(examples, k, precision, recall);
  }
  return 0;
}

int runPrintWordVectors(const std::vector<std::string>& argv) {
  if (argv.size() < 1) {
    std::cerr << "usage: fasttext print-word-vectors <model>\n\n";
    std::cerr << "  <model>      model filename\n";
    return 1;
  }
  Model model = loadModel(argv[0]);
  std::string token;
  while (std::cin >> token) {
    std::cout << token << ' ';
    const std::vector<float> values = wordVector(model, token);
    for (float value : values) {
      std::cout << value << ' ';
    }
    std::cout << '\n';
  }
  return 0;
}

int runPrintSentenceVectors(const std::vector<std::string>& argv) {
  if (argv.size() < 1) {
    std::cerr << "usage: fasttext print-sentence-vectors <model>\n\n";
    std::cerr << "  <model>      model filename\n";
    return 1;
  }
  Model model = loadModel(argv[0]);
  std::string line;
  while (std::getline(std::cin, line)) {
    std::vector<float> sentence(model.args.dim, 0.0f);
    int used = 0;
    for (const std::string& token : splitWhitespace(line)) {
      const std::vector<float> values = wordVector(model, token);
      if (norm(values) == 0.0) {
        continue;
      }
      for (int d = 0; d < model.args.dim; ++d) {
        sentence[d] += values[d];
      }
      ++used;
    }
    if (used > 0) {
      for (float& value : sentence) {
        value /= static_cast<float>(used);
      }
      const double sentenceNorm = norm(sentence);
      if (sentenceNorm > 0.0) {
        for (float& value : sentence) {
          value = static_cast<float>(value / sentenceNorm);
        }
      }
    }
    for (int d = 0; d < model.args.dim; ++d) {
      if (d != 0) {
        std::cout << ' ';
      }
      std::cout << sentence[d];
    }
    std::cout << '\n';
  }
  return 0;
}

int runPrintNgrams(const std::vector<std::string>& argv) {
  if (argv.size() < 2) {
    std::cerr << "usage: fasttext print-ngrams <model> <word>\n\n";
    std::cerr << "  <model>      model filename\n";
    std::cerr << "  <word>       word to print\n";
    return 1;
  }
  Model model = loadModel(argv[0]);
  const std::string& token = argv[1];
  if (model.dict.wordIndex.find(token) == model.dict.wordIndex.end()) {
    return 0;
  }
  auto printRow = [&](const std::string& name, const std::vector<float>& values) {
    std::cout << name << ' ';
    for (float value : values) {
      std::cout << value << ' ';
    }
    std::cout << '\n';
  };
  printRow(token, wordVector(model, token));
  for (const std::string& ngram : subwordStrings(token, model.args.minn, model.args.maxn)) {
    const int bucketId = model.args.bucket <= 0
                             ? 0
                             : static_cast<int>(fnv1a(ngram) %
                                                static_cast<std::uint32_t>(model.args.bucket));
    const std::vector<float>* values = findBucketVector(model, bucketId);
    printRow(ngram, values == nullptr ? zeros(model.args.dim) : *values);
  }
  return 0;
}

void printNearestNeighbors(const Model& model, const std::vector<float>& query,
                           const std::unordered_set<std::string>& excluded, int k) {
  std::vector<std::pair<std::string, double>> scores;
  const double queryNorm = norm(query);
  for (int i = 0; i < model.dict.numWords; ++i) {
    const std::string& token = model.dict.entries[i].token;
    if (excluded.count(token) != 0) {
      continue;
    }
    const std::vector<float> candidate = wordVector(model, token);
    const double candidateNorm = norm(candidate);
    if (queryNorm == 0.0 || candidateNorm == 0.0) {
      continue;
    }
    const double similarity = dot(query, candidate) / (queryNorm * candidateNorm);
    scores.push_back({token, similarity});
  }
  std::stable_sort(scores.begin(), scores.end(),
                   [](const auto& lhs, const auto& rhs) { return lhs.second > rhs.second; });
  const int limit = std::min<int>(k, scores.size());
  for (int i = 0; i < limit; ++i) {
    std::cout << scores[i].first << ' ' << scores[i].second << '\n';
  }
}

int runNN(const std::vector<std::string>& argv) {
  if (argv.size() < 1) {
    std::cerr << "usage: fasttext nn <model> <k>\n\n";
    std::cerr << "  <model>      model filename\n";
    std::cerr << "  <k>          (optional; 10 by default) predict top k labels\n";
    return 1;
  }
  const int k = argv.size() >= 2 ? std::stoi(argv[1]) : 10;
  Model model = loadModel(argv[0]);
  while (true) {
    std::cout << "Query word? " << std::flush;
    std::string word;
    if (!(std::cin >> word)) {
      break;
    }
    const std::vector<float> query = wordVector(model, word);
    printNearestNeighbors(model, query, {word}, k);
  }
  return 0;
}

int runAnalogies(const std::vector<std::string>& argv) {
  if (argv.size() < 1) {
    std::cerr << "usage: fasttext analogies <model> <k>\n\n";
    std::cerr << "  <model>      model filename\n";
    std::cerr << "  <k>          (optional; 10 by default) predict top k labels\n";
    return 1;
  }
  const int k = argv.size() >= 2 ? std::stoi(argv[1]) : 10;
  Model model = loadModel(argv[0]);
  std::cout << "Loading model " << argv[0] << '\n';
  std::string a;
  std::string b;
  std::string c;
  while (true) {
    std::cout << "Query triplet (A - B + C)? " << std::flush;
    std::cin >> a >> b >> c;
    std::vector<float> query = wordVector(model, a);
    const std::vector<float> vb = wordVector(model, b);
    const std::vector<float> vc = wordVector(model, c);
    for (int d = 0; d < model.args.dim; ++d) {
      query[d] = query[d] - vb[d] + vc[d];
    }
    printNearestNeighbors(model, query, {a, b, c}, k);
  }
  return 0;
}

int runDump(const std::vector<std::string>& argv) {
