    std::cout << "loss " << lossToString(model.args.loss) << '\n';
    std::cout << "model " << modelToDumpString(model.args.model) << '\n';
    std::cout << "bucket " << model.args.bucket << '\n';
    std::cout << "minn " << model.args.minn << '\n';
    std::cout << "maxn " << model.args.maxn << '\n';
    std::cout << "lrUpdateRate " << model.args.lrUpdateRate << '\n';
    std::cout << "t " << model.args.t << '\n';
    return 0;
  }
  if (option == "dict") {
    std::cout << model.dict.entries.size() << '\n';
