int main(int argc, char** argv) {
  if (argc < 2) {
    printTopUsage(std::cerr);
    return 1;
  }

  const std::string command = argv[1];
  const std::vector<std::string> args(argv + 2, argv + argc);

  if (command == "supervised") {
    return runTrainingCommand(ModelKind::kSupervised, args);
  }
  if (command == "skipgram") {
    return runTrainingCommand(ModelKind::kSkipgram, args);
  }
  if (command == "cbow") {
    return runTrainingCommand(ModelKind::kCbow, args);
  }
  if (command == "quantize") {
    return runQuantize(args);
  }
  if (command == "predict") {
    return runPredictLike(args, false);
  }
  if (command == "predict-prob") {
    return runPredictLike(args, true);
  }
  if (command == "test") {
    return runTest(args, false);
  }
  if (command == "test-label") {
    return runTest(args, true);
  }
  if (command == "print-word-vectors") {
    return runPrintWordVectors(args);
  }
  if (command == "print-sentence-vectors") {
    return runPrintSentenceVectors(args);
  }
  if (command == "print-ngrams") {
    return runPrintNgrams(args);
  }
  if (command == "nn") {
    return runNN(args);
  }
  if (command == "analogies") {
    return runAnalogies(args);
  }
  if (command == "dump") {
    return runDump(args);
  }

  printTopUsage(std::cerr);
  return 1;
}

